BEGIN;
-- 1) ما معنى الناسخ والمنسوخ في علوم القرآن؟
UPDATE qa_questions SET answer='النسخ هو رفع حكم شرعي سابق بدليل شرعي متأخر عنه، وهو باب معروف في علوم القرآن يفسر بعض التدرج التشريعي (كنسخ عدة الوفاة بالحول إلى أربعة أشهر وعشر)، وهو محدود العدد عند التحقيق لا واسع كما يُظن أحيانًا.',
       evidence='قال السيوطي في النوع السابع والأربعين (في ناسخه ومنسوخه): «النَّسْخُ مِمَّا خَصَّ اللَّهُ بِهِ هَذِهِ الْأُمَّةَ لِحِكَمٍ مِنْهَا التَّيْسِيرُ وَقَدْ أَجْمَعَ الْمُسْلِمُونَ عَلَى جَوَازِهِ»، وردّ ظنَّ من عدَّه بَداءً: «وَهُوَ بَاطِلٌ لِأَنَّهُ بَيَانُ مُدَّةِ الْحُكْمِ» — الإتقان ج٣/ص٦٧. ومن أمثلته المصرَّح بها عنده: «{وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ} إِلَى قَوْلِهِ: {مَتَاعاً إِلَى الْحَوْلِ} مَنْسُوخَةٌ بِآيَةِ {أَرْبَعَةَ أَشْهُرٍ وَعَشْراً}» (ج٣/ص٧٣). وحرَّر عددها فقال: «فَهَذِهِ إِحْدَى وَعِشْرُونَ آيَةً مَنْسُوخَةً عَلَى خِلَافٍ فِي بَعْضِهَا» (ج٣/ص٧٦)، ثم «فَتَمَّتْ عِشْرُونَ» (ج٣/ص٧٧) ونظمها بقوله: «قَدْ أَكْثَرَ النَّاسُ فِي الْمَنْسُوخِ مِنْ عَدَدٍ وَأَدْخَلُوا فِيهِ آيًا لَيْسَ تَنْحَصِرُ».',
       reference='الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (الهيئة المصرية العامة للكتاب): ج٣/ص٦٧ و٧٣ و٧٦-٧٧ (النوع السابع والأربعون) | الكلمات المفتاحية: الناسخ والمنسوخ، علوم القرآن',
       source_url='https://shamela.ws/book/11728/831',
       verification_status='verified',
       updated_at=now()
 WHERE id='0d8bb51e-2e78-4c3b-b992-cd19f981c270'
   AND reference='الإتقان في علوم القرآن للسيوطي | الكلمات المفتاحية: الناسخ والمنسوخ، علوم القرآن'
   AND evidence='باب مشهور في كتب علوم القرآن، كالإتقان للسيوطي والناسخ والمنسوخ لابن الجوزي.'
   AND answer='النسخ هو رفع حكم شرعي سابق بدليل شرعي متأخر عنه، وهو باب معروف في علوم القرآن يفسر بعض التدرج التشريعي (كتدرج تحريم الخمر)، وهو محدود العدد عند التحقيق لا واسع كما يُظن أحيانًا.';
-- 2) من الذي جمع القرآن في مصحف واحد موحَّد بعد النبي ﷺ؟
UPDATE qa_questions SET evidence='نقل السيوطي في النوع الثامن عشر (في جمعه وترتيبه) ما رواه البخاري عن زيد بن ثابت: «أَرْسَلَ إِلَيَّ أَبُو بَكْرٍ مَقْتَلَ أَهْلِ الْيَمَامَةِ»، وفيه قول عمر: «إِنَّ الْقَتْلَ قَدِ اسْتَحَرَّ بِقُرَّاءِ الْقُرْآنِ... وَإِنِّي أَرَى أَنْ تَأْمُرَ بِجَمْعِ الْقُرْآنِ»، وقول زيد: «فَتَتَبَّعْتُ الْقُرْآنَ أَجْمَعُهُ مِنَ الْعُسُبِ وَاللِّخَافِ وَصُدُورِ الرِّجَالِ» — الإتقان ج١/ص٢٠٣. وقال: «فَكَانَ أَبُو بَكْرٍ أَوَّلَ مَنْ جَمَعَ الْقُرْآنَ فِي الصُّحُفِ»، ثم كان جمع عثمان لمّا قال له حذيفة: «أَدْرِكِ الْأُمَّةَ قَبْلَ أَنْ يَخْتَلِفُوا اخْتِلَافَ الْيَهُودِ وَالنَّصَارَى»، فنُسخت الصحف في المصاحف «وَأَرْسَلَ إِلَى كُلِّ أُفُقٍ بِمُصْحَفٍ مِمَّا نَسَخُوا» (ج١/ص٢٠٨).',
       reference='الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (الهيئة المصرية العامة للكتاب): ج١/ص٢٠٣ و٢٠٨ (النوع الثامن عشر) | الكلمات المفتاحية: جمع القرآن، المصحف العثماني',
       source_url='https://shamela.ws/book/11728/196',
       verification_status='verified',
       updated_at=now()
 WHERE id='7348eb60-9039-44f8-bd5c-60f8d3495547'
   AND reference='الإتقان في علوم القرآن للسيوطي | الكلمات المفتاحية: جمع القرآن، المصحف العثماني'
   AND evidence='مذكور في كتب علوم القرآن وتاريخ جمعه.';
-- 3) ما الفرق بين السور المكية والمدنية؟
UPDATE qa_questions SET answer='على أشهر اصطلاحات العلماء الثلاثة: المكية ما نزلت قبل الهجرة النبوية سواء نزلت بمكة أم بغيرها (وغالبها في التوحيد والعقيدة وقصص الأمم)، والمدنية ما نزلت بعد الهجرة (وغالبها في التشريع والأحكام ومعاملات المجتمع).',
       evidence='قال السيوطي في النوع الأول (في معرفة المكي والمدني): «اعْلَمْ أَنَّ لِلنَّاسِ فِي الْمَكِّيِّ وَالْمَدَنِيِّ اصْطِلَاحَاتٌ ثَلَاثَةٌ: أَشْهَرُهَا: أَنَّ الْمَكِّيَّ مَا نَزَلَ قَبْلَ الْهِجْرَةِ وَالْمَدَنِيَّ مَا نَزَلَ بَعْدَهَا سَوَاءٌ نَزَلَ بِمَكَّةَ أَمْ بِالْمَدِينَةِ» — الإتقان ج١/ص٣٧. وأمّا الغالب على موضوعات كلٍّ منهما فنقل فيه ما أخرجه البيهقي في الدلائل عن عروة بن الزبير: «كُلُّ شَيْءٍ نَزَلَ مِنَ الْقُرْآنِ فِيهِ ذِكْرُ الْأُمَمِ وَالْقُرُونِ فَإِنَّمَا نَزَلَ بِمَكَّةَ وَمَا كَانَ مِنَ الْفَرَائِضِ وَالسُّنَنِ فَإِنَّمَا نَزَلَ بِالْمَدِينَةِ» (ج١/ص٦٩).',
       reference='الإتقان في علوم القرآن للسيوطي، ت محمد أبو الفضل إبراهيم (الهيئة المصرية العامة للكتاب): ج١/ص٣٧ و٦٩ (النوع الأول) | الكلمات المفتاحية: مكي ومدني، علوم القرآن',
       source_url='https://shamela.ws/book/11728/30',
       verification_status='verified',
       updated_at=now()
 WHERE id='a471ba55-c8cb-4b1d-8893-16aeac4f32ea'
   AND reference='الإتقان في علوم القرآن للسيوطي | الكلمات المفتاحية: مكي ومدني، علوم القرآن'
   AND evidence='تقسيم مشهور عند علماء علوم القرآن، مبسوط في كتب علوم القرآن (كالإتقان للسيوطي).'
   AND answer='المكية ما نزلت قبل الهجرة النبوية (غالبًا تتناول التوحيد والعقيدة وقصص الأمم)، والمدنية ما نزلت بعد الهجرة (غالبًا تتناول التشريع والأحكام ومعاملات المجتمع).';
COMMIT;
